function stripHtml(s = "") {
  return String(s)
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function decodeEntities(str = "") {
  return String(str)
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

// takes ALL items (Run once for all items)
const posts = $input.all().map(i => i.json);

return posts.map(p => {
  const title = decodeEntities(stripHtml(p.title?.rendered ?? p.title ?? ""));
  const excerpt = decodeEntities(stripHtml(p.excerpt?.rendered ?? p.excerpt ?? ""));
  const content = decodeEntities(stripHtml(p.content?.rendered ?? p.content ?? ""));
  const url = String(p.link ?? "").trim();

  // Indexed text: title + excerpt + content (so keywords like "kali" match anywhere)
  // Note: if you want to limit the content length, truncate content to N characters.
  const text = [
    title ? `Title: ${title}` : "",
    excerpt ? `Excerpt: ${excerpt}` : "",
    content ? `Content: ${content}` : "",
  ].filter(Boolean).join("\n\n");

  return {
    json: {
      // Field that the Default Data Loader will use as content
      content: text,

      // FLAT Metadata (for mapping in the Default Data Loader)
      title,
      url,
      postId: String(p.id ?? ""),
      slug: String(p.slug ?? "")
    }
  };
});

