  // Try to find the JSON if there's text around it
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    cleaned = jsonMatch[0];
  }

  // Parse the JSON
  try {
    const parsed = JSON.parse(cleaned);

    // Transform skills into results
    return [{
      json: {
        type: "search_results",
        query: parsed.query ?? "",
        results: (parsed.skills ?? []).map(skill => ({
          title: skill.skill_name ?? skill.name ?? "Skill",
