          summary: formatSkillDescription(skill)
        })),
        follow_up: parsed.follow_up ?? "Would you like to explore any specific skill in more detail?"
      }
    }];

  } catch (parseError) {
    console.error("JSON parsing error:", parseError);
    console.error("Raw output:", rawOutput);
    console.error("Cleaned output:", cleaned);

    // Fallback: create an error response
    return [{
      json: {
        type: "search_results",
        query: $items("Code-Request_Parsing")[0]?.json?.chatInput ?? "",
        results: [],
        follow_up: "An error occurred in the response format. Could you rephrase the question?"
